describe('Email Field Inline Validation', () => {
  beforeEach(() => {
    cy.visit('/signup');
  });

  it('should display inline validation error when email format is invalid', () => {
    cy.get('[data-testid="email-input"]').type('invalid-email');
    cy.get('[data-testid="email-error-message"]').should('be.visible');
    cy.get('[data-testid="email-error-message"]').should('contain', 'Please enter a valid email address');
    cy.get('[data-testid="email-input"]').should('have.class', 'input-error');
  });

  it('should clear inline validation error when email format becomes valid', () => {
    cy.get('[data-testid="email-input"]').type('invalid-email');
    cy.get('[data-testid="email-error-message"]').should('be.visible');
    cy.get('[data-testid="email-input"]').should('have.class', 'input-error');
    cy.get('[data-testid="email-input"]').clear().type('user@example.com');
    cy.get('[data-testid="email-error-message"]').should('not.exist');
    cy.get('[data-testid="email-input"]').should('not.have.class', 'input-error');
  });
});
